class Solution {
    public int numberOfNodes(int n, int[] queries) {
        int[] flip = new int[n + 1];
        for (int q : queries) flip[q] ^= 1;
        int ans = 0;
        for (int v = 1; v <= n; v++) {
            if (v > 1) flip[v] ^= flip[v / 2];
            ans += flip[v];
        }
        return ans;
    }
}
